1	// See README.md for license details.
2	// -----------------------------------------------------------------------------
3	//  instrDecoder.scala — combinational 32-bit instruction word → DecodedMicroOp
4	//
5	//  One clock cycle: combinational only, no registers.
6	//  The decoded bundle reaches execution units in the same issue cycle.
7	//
8	//  Illegal instruction detection:
9	//    - Reserved opcode family → illegal
10	//    - Reserved funct3 within a family → illegal
11	//    - VecDtypeCls = 11 (reserved) in funct7[6:5] → illegal
12	//    - Width = 11 (reserved) in funct7[1:0] → illegal
13	//    - vcvt src == dst format → illegal
14	// -----------------------------------------------------------------------------
15	
16	package isa
17	
18	import chisel3._
19	import chisel3.util._
20	import isa.micro_op._
21	
22	// ---------------------------------------------------------------------------
23	// DecodedMicroOp — output bundle of InstrDecoder
24	// ---------------------------------------------------------------------------
25	class DecodedMicroOp extends Bundle {
26	  val family    = OpFamily()
27	  val valu      = new NCoreVALUBundle
28	  val mma_keep  = Bool()          // MMALU: keep/accumulate signal
29	  val mma_last  = Bool()          // MMALU: assert clct
30	  val mma_reset = Bool()          // MMALU: clear accumulator
31	  val rd        = UInt(5.W)
32	  val rs1       = UInt(5.W)
33	  val rs2       = UInt(5.W)
34	  val mem_width = UInt(3.W)       // ld/st funct3
35	}
36	
37	// ---------------------------------------------------------------------------
38	// InstrDecoder — pure combinational module
39	// ---------------------------------------------------------------------------
40	class InstrDecoder extends Module {
41	  val io = IO(new Bundle {
42	    val instr   = Input(UInt(32.W))
43	    val decoded = Output(new DecodedMicroOp)
44	    val illegal = Output(Bool())
45	  })
46	
47	  // ---------- Field extraction ----------
48	  val opBits  = io.instr(InstrBits.OPCODE_HI, InstrBits.OPCODE_LO)  // [6:0]
49	  val rdBits  = io.instr(InstrBits.RD_HI,     InstrBits.RD_LO)      // [11:7]
50	  val f3      = io.instr(InstrBits.FUNCT3_HI,  InstrBits.FUNCT3_LO)  // [14:12]
51	  val rs1Bits = io.instr(InstrBits.RS1_HI,     InstrBits.RS1_LO)     // [19:15]
52	  val rs2Bits = io.instr(InstrBits.RS2_HI,     InstrBits.RS2_LO)     // [24:20]
53	  val f7      = io.instr(InstrBits.FUNCT7_HI,  InstrBits.FUNCT7_LO)  // [31:25]
54	
55	  // I-type immediate (sign-extended 12 bits)
56	  val immI    = io.instr(InstrBits.IMM_I_HI, InstrBits.IMM_I_LO).asSInt
57	
58	  // S-type fields (FMA)
59	  val rs3Bits = io.instr(InstrBits.RS3_HI, InstrBits.RS3_LO)
60	  val rndS    = io.instr(InstrBits.RND_S_HI, InstrBits.RND_S_LO)
61	
62	  // funct7 attribute sub-fields
63	  val f7Width = f7(InstrBits.F7_WIDTH_HI, InstrBits.F7_WIDTH_LO)
64	  val f7Round = f7(InstrBits.F7_ROUND_HI, InstrBits.F7_ROUND_LO)
65	  val f7Sat   = f7(InstrBits.F7_SAT)
66	  val f7Dtype = f7(InstrBits.F7_DTYPE_HI, InstrBits.F7_DTYPE_LO)
67	
68	  // cvt-specific funct7 sub-fields
69	  val f7CvtSrc = f7(InstrBits.F7_CVT_SRC_HI, InstrBits.F7_CVT_SRC_LO)
70	  val f7CvtSat = f7(InstrBits.F7_CVT_SAT)
71	  val f7CvtRnd = f7(InstrBits.F7_CVT_RND_HI, InstrBits.F7_CVT_RND_LO)
72	  val f7Bf8    = f7(InstrBits.F7_CVT_BF8)
73	
74	  // Try to decode opcode family.
75	  // OpFamily auto-infers minimum bit width (5 bits for max value 0x18=24).
76	  // opBits is 7 bits; truncate to match the enum width (5) before safe-cast.
77	  // 5 = ceil(log2(0x18 + 1)) computed at Scala level.
78	  val OP_FAMILY_BITS = 5  // covers 0x00..0x18 = 0..24
79	  val opBitsTrunc = opBits(OP_FAMILY_BITS - 1, 0)
80	  val familyOpt = OpFamily.safe(opBitsTrunc)
81	  val familyOK  = familyOpt._2
82	  val family    = familyOpt._1
83	
84	  // ---------- VALU op decode (opcode+funct3 → VecOp) ----------
85	
86	  // Map (family, funct3) → VecOp.  Use a big MuxCase to stay Chisel-idiomatic.
87	  // Default = vadd (harmless; illegal flag suppresses write-back)
88	  val vecOp = WireDefault(VecOp.vadd)
89	  val f3Valid = WireDefault(true.B)
90	
91	  switch (family) {
92	    is (OpFamily.VALU_ARITH) {
93	      switch (f3) {
94	        is (Funct3Arith.ADD)  { vecOp := VecOp.vadd  }
95	        is (Funct3Arith.SUB)  { vecOp := VecOp.vsub  }
96	        is (Funct3Arith.MUL)  { vecOp := VecOp.vmul  }
97	        is (Funct3Arith.NEG)  { vecOp := VecOp.vneg  }
98	        is (Funct3Arith.ABS)  { vecOp := VecOp.vabs  }
99	        is (Funct3Arith.MAX)  { vecOp := VecOp.vmax  }
100	        is (Funct3Arith.MIN)  { vecOp := VecOp.vmin  }
101	        is (Funct3Arith.RSUB) { vecOp := VecOp.vrsub }
102	      }
103	    }
104	    is (OpFamily.VALU_LOGIC) {
105	      switch (f3) {
106	        is (Funct3Logic.SLL) { vecOp := VecOp.vsll }
107	        is (Funct3Logic.SRL) { vecOp := VecOp.vsrl }
108	        is (Funct3Logic.SRA) { vecOp := VecOp.vsra }
109	        is (Funct3Logic.ROL) { vecOp := VecOp.vrol }
110	        is (Funct3Logic.XOR) { vecOp := VecOp.vxor }
111	        is (Funct3Logic.NOT) { vecOp := VecOp.vnot }
112	        is (Funct3Logic.OR)  { vecOp := VecOp.vor  }
113	        is (Funct3Logic.AND) { vecOp := VecOp.vand }
114	      }
115	    }
116	    is (OpFamily.VALU_REDUCE) {
117	      switch (f3) {
118	        is (Funct3Reduce.SUM)  { vecOp := VecOp.vsum  }
119	        is (Funct3Reduce.RMAX) { vecOp := VecOp.vrmax }
120	        is (Funct3Reduce.RMIN) { vecOp := VecOp.vrmin }
121	        is (Funct3Reduce.RAND) { vecOp := VecOp.vrand }
122	        is (Funct3Reduce.ROR)  { vecOp := VecOp.vror  }
123	        is (Funct3Reduce.RXOR) { vecOp := VecOp.vrxor }
124	      }
125	    }
126	    is (OpFamily.VALU_LUT) {
127	      // vlut (funct3=0/1): R-type lookup. Bank A (0) or B (1) via funct3[0],
128	      //   propagated as round[0] in the decoded bundle.
129	      // vsetlut (funct3=4/5): I-type segment write. Bank A (4) or B (5).
130	      //   imm carries the segment index; no register-file write.
131	      // funct3 2, 3, 6, 7: reserved — flag as illegal.
132	      switch (f3) {
133	        is (Funct3Lut.VLUT_A)    { vecOp := VecOp.vlut    }
134	        is (Funct3Lut.VLUT_B)    { vecOp := VecOp.vlut    }
135	        is (Funct3Lut.VSETLUT_A) { vecOp := VecOp.vsetlut }
136	        is (Funct3Lut.VSETLUT_B) { vecOp := VecOp.vsetlut }
137	      }
138	      // illegal: reserved funct3 values 2, 3, 6, 7
139	      when (f3 === 2.U || f3 === 3.U || f3 === 6.U || f3 === 7.U) {
140	        f3Valid := false.B
141	      }
142	    }
143	    is (OpFamily.VALU_CVT) {
144	      // funct3 = dst format; funct7[2:0] = src format
145	      val dst = f3
146	      val src = f7CvtSrc
147	      val bf8 = f7Bf8
148	      // decode into VecOp
149	      vecOp := MuxCase(VecOp.vadd, Seq(
150	        (dst === FmtCode.S8  && src === FmtCode.S32)  -> VecOp.vcvt_s8_s32,
151	        (dst === FmtCode.S32 && src === FmtCode.S8)   -> VecOp.vcvt_s32_s8,
152	        (dst === FmtCode.S32 && src === FmtCode.F32)  -> VecOp.vcvt_s32_f32,
153	        (dst === FmtCode.F32 && src === FmtCode.S32)  -> VecOp.vcvt_f32_s32,
154	        (dst === FmtCode.F32 && src === FmtCode.S8)   -> VecOp.vcvt_f32_s8,
155	        (dst === FmtCode.S8  && src === FmtCode.F32)  -> VecOp.vcvt_s8_f32,
156	        (dst === FmtCode.F32 && src === FmtCode.BF16) -> VecOp.vcvt_f32_bf16,
157	        (dst === FmtCode.BF16 && src === FmtCode.F32) -> VecOp.vcvt_bf16_f32,
158	        (dst === FmtCode.F32 && src === FmtCode.BF8)  -> VecOp.vcvt_f32_bf8,
159	        (dst === FmtCode.BF8 && src === FmtCode.F32)  -> VecOp.vcvt_bf8_f32,
160	        (dst === FmtCode.S16 && src === FmtCode.S32)  -> VecOp.vcvt_s16_s32,
161	        (dst === FmtCode.S32 && src === FmtCode.S16)  -> VecOp.vcvt_s32_s16,
162	      ))
163	      // illegal: same src and dst
164	      when (dst === src) { f3Valid := false.B }
165	    }
166	    is (OpFamily.VALU_BCAST) {
167	      switch (f3) {
168	        is (Funct3Bcast.REG) { vecOp := VecOp.vbcast_reg }
169	        is (Funct3Bcast.IMM) { vecOp := VecOp.vbcast_imm }
170	        // default: f3Valid = true but vecOp harmless; non-listed values not hit via safe
171	      }
172	    }
173	    is (OpFamily.VALU_FP) {
174	      switch (f3) {
175	        is (Funct3Fp.FADD) { vecOp := VecOp.vfadd }
176	        is (Funct3Fp.FSUB) { vecOp := VecOp.vfsub }
177	        is (Funct3Fp.FMUL) { vecOp := VecOp.vfmul }
178	        is (Funct3Fp.FNEG) { vecOp := VecOp.vfneg }
179	        is (Funct3Fp.FABS) { vecOp := VecOp.vfabs }
180	        is (Funct3Fp.FMAX) { vecOp := VecOp.vfmax }
181	        is (Funct3Fp.FMIN) { vecOp := VecOp.vfmin }
182	      }
183	    }
184	    is (OpFamily.VALU_FP_FMA) {
185	      switch (f3) {
186	        is (Funct3Fma.FMA)  { vecOp := VecOp.vfma  }
187	        is (Funct3Fma.FMS)  { vecOp := VecOp.vfms  }
188	        is (Funct3Fma.NFMA) { vecOp := VecOp.vnfma }
189	        is (Funct3Fma.NFMS) { vecOp := VecOp.vnfms }
190	      }
191	    }
192	    is (OpFamily.VALU_MOV) {
193	      switch (f3) {
194	        is (Funct3Mov.MOV)  { vecOp := VecOp.vmov  }
195	        is (Funct3Mov.MOVI) { vecOp := VecOp.vmovi }
196	        is (Funct3Mov.MOVH) { vecOp := VecOp.vmovh }
197	      }
198	    }
199	    // MMA, LD, ST, NOP: vecOp stays at default (not used)
200	  }
201	
202	  // ---------- Width decode — drive as raw UInt(2.W) to match NCoreVALUBundle ----------
203	  // VX=0, VE=1, VR=2 (matches VecWidth enum values)
204	  val width = WireDefault(0.U(2.W))  // default = VX
205	  when (f7Width === 1.U) { width := 1.U }  // VE
206	  .elsewhen (f7Width === 2.U) { width := 2.U }  // VR
207	  // FP family always uses VR
208	  when (family === OpFamily.VALU_FP || family === OpFamily.VALU_FP_FMA) {
209	    width := 2.U  // VR
210	  }
211	  // CVT: for simplicity set width to VR (widest); actual regCls determined by the
212	  // backend based on the VecOp. The VALU handles width selection per-op internally.
213	  when (family === OpFamily.VALU_CVT) {
214	    width := 2.U  // VR — conservative; backend picks correct src/dst via VecOp
215	  }
216	  // BCAST IMM (I-format): no funct7, width defaults to VX (IMM always goes to VX)
217	  when (family === OpFamily.VALU_BCAST && f3 === Funct3Bcast.IMM) {
218	    width := 0.U  // VX
219	  }
220	  // vsetlut (I-format): reads from a VR source register → force VR width so
221	  // the backend routes in_a_vr correctly.
222	  when (family === OpFamily.VALU_LUT &&
223	        (f3 === Funct3Lut.VSETLUT_A || f3 === Funct3Lut.VSETLUT_B)) {
224	    width := 2.U  // VR
225	  }
226	  // Width bits are repurposed for src format in CVT family; skip width check for CVT.
227	  val widthIllegal = (f7Width === 3.U) &&
228	    (family =/= OpFamily.VALU_FP) &&
229	    (family =/= OpFamily.VALU_FP_FMA) &&
230	    (family =/= OpFamily.VALU_CVT)
231	
232	  // ---------- Dtype decode ----------
233	  // BF8 variant from funct7[6] (cvt family) or bf8E5M2 forced
234	  val dtype = WireDefault(VecDType.S8C4)
235	  switch (f7Dtype) {
236	    is (1.U) { dtype := VecDType.FP32C1 }
237	    is (2.U) {
238	      // BF class: BF16 unless BF8 format codes are in play
239	      dtype := VecDType.BF16C2
240	    }
241	  }
242	  // For CVT, override with BF8 variant
243	  when (family === OpFamily.VALU_CVT) {
244	    when (f7Bf8 === 1.U) { dtype := VecDType.BF8E5M2 }
245	    .otherwise           { dtype := VecDType.BF8E4M3  }
246	  }
247	
248	  val dtypeIllegal = (f7Dtype === 3.U)
249	
250	  // ---------- MMA control ----------
251	  val mmaKeep  = WireDefault(false.B)
252	  val mmaLast  = WireDefault(false.B)
253	  val mmaReset = WireDefault(false.B)
254	  when (family === OpFamily.MMA) {
255	    switch (f3) {
256	      is (Funct3Mma.MMA)       { mmaKeep  := f7Sat.asBool }   // reuse sat bit for keep
257	      is (Funct3Mma.MMA_LAST)  { mmaLast  := true.B }
258	      is (Funct3Mma.MMA_RESET) { mmaReset := true.B }
259	    }
260	  }
261	
262	  // ---------- Illegal detection ----------
263	  val illegal = WireDefault(false.B)
264	  when (!familyOK)    { illegal := true.B }
265	  when (!f3Valid)     { illegal := true.B }
266	  when (widthIllegal) { illegal := true.B }
267	  when (dtypeIllegal) { illegal := true.B }
268	
269	  // ---------- Drive outputs ----------
270	  io.illegal := illegal
271	
272	  io.decoded.family    := family
273	  io.decoded.rd        := rdBits
274	  io.decoded.rs1       := rs1Bits
275	  io.decoded.rs2       := rs2Bits
276	  io.decoded.mem_width := f3
277	
278	  io.decoded.mma_keep  := mmaKeep
279	  io.decoded.mma_last  := mmaLast
280	  io.decoded.mma_reset := mmaReset
281	
282	  // VALU control bundle
283	  io.decoded.valu.op       := vecOp
284	  io.decoded.valu.regCls    := width
285	  io.decoded.valu.dtype    := dtype
286	  // For CVT, sat bit is at funct7[3] not funct7[4]
287	  io.decoded.valu.saturate := Mux(family === OpFamily.VALU_CVT, f7CvtSat.asBool, f7Sat.asBool)
288	  // For LUT ops, round[0] carries the bank select (taken from funct3[0]):
289	  //   vlut.A (f3=0) → round=0, vlut.B (f3=1) → round=1
290	  //   vsetlut.A (f3=4) → round=0, vsetlut.B (f3=5) → round=1
291	  io.decoded.valu.round    := Mux(
292	    family === OpFamily.VALU_FP_FMA,
293	    rndS,
294	    Mux(family === OpFamily.VALU_CVT, f7CvtRnd,
295	      Mux(family === OpFamily.VALU_LUT, Cat(0.U(1.W), f3(0)),
296	        f7Round))
297	  )
298	  io.decoded.valu.rs3_idx  := rs3Bits
299	  io.decoded.valu.imm      := immI
300	}
301

